document.querySelector('#soundless-theme').addEventListener('click',()=>{const dark=document.body.classList.toggle('dark');document.querySelector('#soundless-theme').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);try{localStorage.setItem('po-theme',dark?'dark':'light')}catch{}});try{if(localStorage.getItem('po-theme')==='dark')document.body.classList.add('dark')}catch{}
function notify(message){clearTimeout(toastTimer);const toast=document.querySelector('#toast');toast.replaceChildren();const icon=document.createElement('span');icon.className='toast-icon';icon.textContent='✓';const copy=document.createElement('span');copy.className='toast-copy';const title=document.createElement('strong');title.textContent='Princewill’s desktop';const detail=document.createElement('span');detail.textContent=message;copy.append(title,detail);const dismiss=document.createElement('button');dismiss.className='toast-close';dismiss.setAttribute('aria-label','Dismiss notification');dismiss.textContent='×';dismiss.onclick=()=>toast.classList.remove('show');toast.append(icon,copy,dismiss);toast.classList.add('show');toastTimer=setTimeout(()=>toast.classList.remove('show'),5000)}
document.addEventListener('submit',async e=>{if(e.target.id!=='brief-form')return;e.preventDefault();const form=e.target,data=new FormData(form),text=`Hi Princewill,\n\nI’m ${data.get('name')}. I’d like to discuss ${data.get('topic').toLowerCase()}.\n\n${data.get('idea')}\n\nLet me know a good time to chat.`;const prepared=document.querySelector('#prepared-brief');prepared.value=text;prepared.hidden=false;try{await navigator.clipboard.writeText(text);document.querySelector('#copy-feedback').textContent='Brief copied. Open LinkedIn below and paste it into your message.';notify('Enquiry copied. You’re ready to say hello.')}catch{document.querySelector('#copy-feedback').textContent='Your brief is ready below. Select and copy it, then send it on LinkedIn.';prepared.focus();prepared.select();}});
function search(query=''){const q=query.trim().toLowerCase(),matches=Object.entries(views).filter(([key,v])=>(key+' '+v.title+' '+v.keywords).toLowerCase().includes(q));const results=document.querySelector('#search-results');results.replaceChildren();if(!matches.length){const p=document.createElement('p');p.textContent='No matches yet. Try “CV”, “IlluminatED” or “brands”.';results.append(p)}for(const [key,v] of matches){const b=document.createElement('button');b.className='search-result';b.dataset.open=key;const label=document.createElement('span');label.textContent=v.title;const sub=document.createElement('small');sub.textContent=v.status;label.append(sub);const arrow=document.createElement('span');arrow.textContent='↗';b.append(label,arrow);results.append(b)}}
function openSearch(){if(!isUnlocked)return;document.querySelector('#search-input').value='';search();if(!spotlight.open)spotlight.showModal();document.querySelector('#search-input').focus()}
document.querySelector('#spotlight-toggle').addEventListener('click',openSearch);document.querySelector('#window-search').addEventListener('click',openSearch);document.querySelector('#search-close').addEventListener('click',()=>spotlight.close());document.querySelector('#search-input').addEventListener('input',e=>search(e.target.value));document.querySelector('#search-input').addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();document.querySelector('.search-result')?.focus()}if(e.key==='Enter'){const first=document.querySelector('.search-result');if(first)openView(first.dataset.open)}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}});
// Desktop windows can be moved by their title bar. Keep enough visible to close them.
let drag=null;const bar=document.querySelector('.window-bar');bar.addEventListener('pointerdown',e=>{if(e.target.closest('button')||finder.classList.contains('maximised')||innerWidth<701)return;const rect=finder.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,dx:Number(finder.dataset.dx)||0,dy:Number(finder.dataset.dy)||0,rect};bar.setPointerCapture(e.pointerId)});bar.addEventListener('pointermove',e=>{if(!drag)return;const x=Math.max(-drag.rect.left+drag.dx+20,Math.min(innerWidth-drag.rect.right+drag.dx-20,drag.dx+e.clientX-drag.x));const y=Math.max(-drag.rect.top+drag.dy+12,Math.min(innerHeight-drag.rect.top+drag.dy-75,drag.dy+e.clientY-drag.y));finder.style.transform=`translate(${x}px,${y}px)`;finder.dataset.dx=x;finder.dataset.dy=y});bar.addEventListener('pointerup',()=>{drag=null});bar.addEventListener('pointercancel',()=>{drag=null});finder.addEventListener('close',()=>{finder.dataset.dx='0';finder.dataset.dy='0';finder.style.transform=''});

