document.querySelector('.avatar').innerHTML='<img src="assets/princewill-linkedin.jpg" alt="Princewill Okube"><svg aria-hidden="true"><use href="#i-spark"/></svg>';
document.querySelector('.dock-finder>span').outerHTML='<img src="assets/princewill-linkedin.jpg" alt="">';
const portrait=document.querySelector('.paper-icon');portrait.classList.add('profile-paper');portrait.innerHTML='<img src="assets/princewill-linkedin.jpg" alt=""><small>hello, it’s me.</small>';
document.querySelector('#desktop-socials').innerHTML=socials.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer" aria-label="${s.name}" title="${s.name}: ${s.handle}">${socialIcon(s)}</a>`).join('');
const sidebar=document.querySelector('.finder-sidebar');sidebar.insertAdjacentHTML('afterbegin','<div class="sidebar-profile"><img src="assets/princewill-linkedin.jpg" alt=""><span>Princewill Okube<small>Builder & creator</small></span></div>');sidebar.querySelector('[data-open="contact"]').insertAdjacentHTML('afterend','<button data-open="socials">@ <span>Find me elsewhere</span></button>');
document.querySelector('.dock-awards').insertAdjacentHTML('afterend','<button data-open="socials" class="dock-icon dock-socials" aria-label="Social media">@<small>My socials</small></button>');
const folderDetails={work:{count:'4',label:'PROJECTS',img:'assets/illumed-world.webp'},services:{count:'6',label:'LET’S BUILD'},achievements:{count:'4',label:'HIGHLIGHTS'},partners:{count:'4',label:'YOUR IDEA'},socials:{count:'5',label:'SAY HELLO'}};
document.querySelectorAll('.desktop-file .folder-wrap').forEach(folder=>{const key=folder.closest('button').dataset.open,details=folderDetails[key];if(!details)return;const papers=document.createElement('span');papers.className='folder-papers';papers.innerHTML=`<span class="folder-paper"><span>PRINCEWILL’S DESKTOP</span></span><span class="folder-paper"><span>${details.label}</span></span><span class="folder-paper">${details.img?`<img src="${details.img}" alt="">`:`<span>${key==='socials'?'@princewillcodes':details.label}</span>`}</span>`;const face=document.createElementNS('http://www.w3.org/2000/svg','svg');face.setAttribute('viewBox','0 0 100 82');face.setAttribute('aria-hidden','true');face.classList.add('folder-front');face.innerHTML='<path d="M8 32Q8 25 15 25H86Q94 25 93 33L89 68Q89 74 82 74H14Q8 74 8 67Z" fill="currentColor"/><path d="M9 33Q9 27 15 27H86Q92 27 91 33L88 67Q88 72 82 72H16Q10 72 10 66Z" fill="white" opacity=".16"/><path d="M15 27H86" stroke="white" stroke-opacity=".7"/>';folder.append(papers,face);const count=document.createElement('span');count.className='folder-count';count.textContent=details.count;folder.append(count);const button=folder.closest('button');button.addEventListener('pointermove',e=>{if(reducedMotion.matches||e.pointerType==='touch')return;const rect=button.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width-.5,y=(e.clientY-rect.top)/rect.height-.5;folder.style.setProperty('--tilt-x',`${-y*15}deg`);folder.style.setProperty('--tilt-y',`${x*23}deg`)});button.addEventListener('pointerleave',()=>{folder.style.removeProperty('--tilt-x');folder.style.removeProperty('--tilt-y')})});
// A proximity curve makes neighbouring dock icons respond to the pointer too.
const dock=document.querySelector('.dock'),dockIcons=[...dock.querySelectorAll('.dock-icon')];
function resetDock(){dockIcons.forEach(icon=>{icon.style.removeProperty('--dock-scale');icon.style.removeProperty('--dock-rise');icon.style.removeProperty('--dock-shift');icon.style.removeProperty('z-index')})}
dock.addEventListener('pointermove',e=>{if(reducedMotion.matches||e.pointerType==='touch'||innerWidth<701)return;const rect=dock.getBoundingClientRect();const scales=dockIcons.map(icon=>{const centre=rect.left+icon.offsetLeft+icon.offsetWidth/2;return 1+.5*Math.pow(Math.max(0,1-Math.abs(e.clientX-centre)/115),2)}),extra=scales.map((scale,i)=>(scale-1)*dockIcons[i].offsetWidth);let shift=-extra.reduce((a,b)=>a+b,0)/2;dockIcons.forEach((icon,i)=>{icon.style.setProperty('--dock-scale',scales[i]);icon.style.setProperty('--dock-rise',`${-(scales[i]-1)*19}px`);icon.style.setProperty('--dock-shift',`${shift+extra[i]/2}px`);icon.style.zIndex=Math.round(scales[i]*10);shift+=extra[i]})});dock.addEventListener('pointerleave',resetDock);
window.addEventListener('resize',()=>{resetDock();if(finder.open){finder.style.transform='';finder.dataset.dx='0';finder.dataset.dy='0'}});
